-- =============================================================================
-- Step 0-1: 마스터 데이터 (팀, 경기장, 연고지, 좌석등급, 좌석구역, 가격정책, 가격)
--
-- 대상 테이블:
--   stadium_service.baseball_teams        (10팀)
--   stadium_service.stadiums              (13개 경기장)
--   stadium_service.home_stadiums         (10개 연고지)
--   ticketing_service.seat_grades         (35개 등급)
--   ticketing_service.seat_sections       (171개 구역)
--   ticketing_service.ticket_pricing_policies (2개 정책)
--   ticketing_service.ticket_prices       (66개 가격)
--
-- 의존성: 없음 (최초 실행)
-- 멱등성: ON CONFLICT DO NOTHING — 재실행 안전
-- =============================================================================

BEGIN;


-- Data for Name: baseball_teams; Type: TABLE DATA; Schema: stadium_service; Owner: goti-db-server

-- Data for Name: stadiums; Type: TABLE DATA; Schema: stadium_service; Owner: goti-db-server

-- Data for Name: home_stadiums; Type: TABLE DATA; Schema: stadium_service; Owner: goti-db-server

-- Data for Name: seat_grades; Type: TABLE DATA; Schema: ticketing_service; Owner: goti-db-server

-- Data for Name: seat_sections; Type: TABLE DATA; Schema: ticketing_service; Owner: goti-db-server

-- Data for Name: ticket_pricing_policies; Type: TABLE DATA; Schema: ticketing_service; Owner: goti-db-server

-- Data for Name: ticket_prices; Type: TABLE DATA; Schema: ticketing_service; Owner: goti-db-server

-- 검증
SELECT 'baseball_teams' AS tbl, COUNT(*) FROM stadium_service.baseball_teams
UNION ALL SELECT 'stadiums', COUNT(*) FROM stadium_service.stadiums
UNION ALL SELECT 'home_stadiums', COUNT(*) FROM stadium_service.home_stadiums
UNION ALL SELECT 'seat_grades', COUNT(*) FROM ticketing_service.seat_grades
UNION ALL SELECT 'seat_sections', COUNT(*) FROM ticketing_service.seat_sections
UNION ALL SELECT 'ticket_pricing_policies', COUNT(*) FROM ticketing_service.ticket_pricing_policies
UNION ALL SELECT 'ticket_prices', COUNT(*) FROM ticketing_service.ticket_prices;

COMMIT;
